"""Serve the port's Fiori Elements app locally: a list report and object page over the new OData V4 service.

UI5 comes from the SAP system itself, and every /sap/ request is passed through to SAP with the factory's user, so
the browser needs no SAP logon. The service and its main entity set come from runs/<TCODE>/port/service.json.

    python3 factory/app.py ZCRED [port]          -> http://127.0.0.1:8100/
"""
import http.server
import json
import os
import re
import sys
import urllib.error
import urllib.request

sys.path.insert(0, os.path.dirname(__file__))
import sap  # noqa: E402

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
PASS_HEADERS = ("content-type", "accept", "x-csrf-token", "if-match", "if-none-match", "prefer", "odata-version",
                "odata-maxversion", "sap-contextid-accept", "sap-cancel-on-close", "x-requested-with")
BACK_HEADERS = ("content-type", "x-csrf-token", "sap-messages", "etag", "odata-version", "location",
                "sap-contextid", "preference-applied")

INDEX = """<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{title}</title>
<script id="sap-ui-bootstrap" src="/sap/public/bc/ui5_ui5/resources/sap-ui-core.js"
  data-sap-ui-theme="sap_horizon" data-sap-ui-async="true" data-sap-ui-compatVersion="edge"
  data-sap-ui-resourceroots='{{"proofport": "./"}}' data-sap-ui-oninit="module:sap/ui/core/ComponentSupport"
  data-sap-ui-language="EN"></script>
<style>html, body {{ height: 100%; margin: 0; }}</style></head>
<body class="sapUiBody sapUiSizeCompact"><div data-sap-ui-component data-name="proofport" data-id="app"
 data-height="100%" data-width="100%" data-settings='{{"id": "proofport"}}' style="height:100%"></div></body></html>"""

COMPONENT = """sap.ui.define(["sap/fe/core/AppComponent"], function (AppComponent) {
  "use strict";
  return AppComponent.extend("proofport.Component", { metadata: { manifest: "json" } });
});"""


def manifest(title, root, entity):
    return {
        "_version": "1.60.0",
        "sap.app": {"id": "proofport", "type": "application", "title": title, "applicationVersion": {"version": "1.0.0"},
                    "dataSources": {"mainService": {"uri": root, "type": "OData",
                                                    "settings": {"odataVersion": "4.0"}}}},
        "sap.ui": {"technology": "UI5", "deviceTypes": {"desktop": True, "tablet": True, "phone": True}},
        "sap.ui5": {
            "flexEnabled": False,
            "dependencies": {"minUI5Version": "1.120.0", "libs": {"sap.m": {}, "sap.ui.core": {}, "sap.fe.templates": {}}},
            "models": {"": {"dataSource": "mainService", "preload": True,
                            "settings": {"operationMode": "Server", "autoExpandSelect": True, "earlyRequests": True}}},
            "routing": {
                "routes": [{"pattern": ":?query:", "name": "List", "target": "List"},
                           {"pattern": entity + "({key}):?query:", "name": "Object", "target": "Object"}],
                "targets": {
                    "List": {"type": "Component", "id": "List", "name": "sap.fe.templates.ListReport",
                             "options": {"settings": {"contextPath": "/" + entity, "variantManagement": "None",
                                                      "initialLoad": "Enabled",
                                                      "navigation": {entity: {"detail": {"route": "Object"}}}}}},
                    "Object": {"type": "Component", "id": "Object", "name": "sap.fe.templates.ObjectPage",
                               "options": {"settings": {"contextPath": "/" + entity, "editableHeaderContent": False}}},
                },
            },
        },
        "sap.fe": {"app": {"title": title}},
    }


def make_handler(tcode, s, service):
    title = f"{tcode}, the new app"

    class Handler(http.server.BaseHTTPRequestHandler):
        def log_message(self, *a):
            pass

        def send(self, code, body, ctype):
            data = body.encode() if isinstance(body, str) else body
            self.send_response(code)
            self.send_header("Content-Type", ctype)
            self.send_header("Content-Length", str(len(data)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            self.wfile.write(data)

        def proxy(self):
            length = int(self.headers.get("Content-Length") or 0)
            body = self.rfile.read(length) if length else None
            path = self.path + ("&" if "?" in self.path else "?") + "sap-client=" + s.client
            headers = {"Authorization": s.auth}
            for h in PASS_HEADERS:
                if self.headers.get(h):
                    headers[h] = self.headers[h]
            req = urllib.request.Request(s.url + path, data=body, method=self.command, headers=headers)
            try:
                resp = s.opener.open(req, timeout=120)
                code, rh, data = resp.status, resp.headers, resp.read()
            except urllib.error.HTTPError as e:
                code, rh, data = e.code, e.headers, e.read()
            self.send_response(code)
            for h in BACK_HEADERS:
                if rh.get(h):
                    self.send_header(h, rh[h])
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)

        def route(self):
            p = self.path.split("?")[0]
            if p.startswith("/sap/"):
                return self.proxy()
            if p in ("/", "/index.html"):
                return self.send(200, INDEX.format(title=title), "text/html; charset=utf-8")
            if p == "/Component.js":
                return self.send(200, COMPONENT, "application/javascript")
            if p == "/manifest.json":
                return self.send(200, json.dumps(manifest(title, service["root"], service["entity"])),
                                 "application/json")
            return self.send(404, "not found", "text/plain")

        do_GET = do_POST = do_PATCH = do_PUT = do_DELETE = do_HEAD = route

    return Handler


def main_entity(s, tcode, service):
    """The entity set the service definition exposes for the behavior definition's root, else the first one."""
    roots = {n.upper() for k, n in service.get("objects", []) if k.upper() == "BDEF"}
    src = os.path.join(ROOT, "runs", tcode, "port", "src")
    for name in sorted(os.listdir(src)) if os.path.isdir(src) else []:
        if name.lower().endswith(".srvd"):
            with open(os.path.join(src, name)) as f:
                for view, alias in re.findall(r"expose\s+(\w+)\s+as\s+(\w+)", f.read(), re.I):
                    if view.upper() in roots:
                        return alias
    _, _, text = s.request("GET", service["root"] + "$metadata", accept="application/xml")
    sets = re.findall(r'<EntitySet Name="([^"]+)"', text)
    return sets[0] if sets else None


def main(tcode, port=8100):
    s = sap.Sap()
    with open(os.path.join(ROOT, "runs", tcode, "port", "service.json")) as f:
        service = json.load(f)
    service.setdefault("entity", main_entity(s, tcode, service))
    server = http.server.ThreadingHTTPServer(("127.0.0.1", port), make_handler(tcode, s, service))
    print(f"{tcode} new app on http://127.0.0.1:{port}/ (entity set {service['entity']})", flush=True)
    server.serve_forever()


if __name__ == "__main__":
    main(sys.argv[1].upper(), int(sys.argv[2]) if len(sys.argv) > 2 else 8100)

class Stop(Exception):
    """The old screen would go no further in this case, so neither do we."""


def blank_row():
    return {"mark": "", "VariantId": "", "Color": "", "SizeCode": "", "Ean": "", "Price": ""}


class Screen:
    """The old transaction's memory between two key presses."""

    def __init__(self, client):
        self.client = client
        self.screen = "0100"
        self.article_id = ""
        self.header = {}
        self.rows = []
        self.tab = "TAB1"

    # -- what the keyboard does to a field -------------------------------------

    def typed(self, raw, width, kind, dynpro_field):
        """One field as the dynpro takes it, or Stop if it would not take it."""
        if raw == "!":
            # A lone exclamation mark empties the field.
            return ""
        if len(raw) > width:
            # Batch input says the value is longer than the field and gives up on
            # the case. It is not an error message, and nothing is saved.
            raise Stop()
        if kind == NUMBER:
            # A numeric field is right aligned, so blanks on either side are no part
            # of what was typed.
            return self.number(raw.strip(), dynpro_field)
        if kind in (CHECK, CHECK_FREE):
            # A check box is not upper cased. The active flag's data element has
            # fixed values, so only the tick and nothing pass; the variant mark has
            # none, so anything a finger lands on is kept as it was typed.
            value = raw.rstrip()
            if kind == CHECK and value not in ("", "X"):
                self.format_error(dynpro_field, "Enter a valid value")
            return value
        value = raw.upper().rstrip()
        if kind != TEXT and value != "" and value not in kind:
            self.format_error(dynpro_field, "Enter a valid value")
        return value

    def number(self, value, dynpro_field):
        """A price as this user types it: 1.234,56. Returns a decimal string."""
        if not value:
            return ""
        if "-" in value:
            # The domain carries no sign, so the dynpro refuses a negative number
            # however it is written, SAP's trailing minus included.
            self.format_error(dynpro_field, "Specify positive values only")
        if any(c not in "0123456789.," for c in value) or value.count(",") > 1:
            self.format_error(dynpro_field, "Enter a numeric value")
        parts = value.split(",")
        whole, fraction = parts[0], (parts[1] if len(parts) == 2 else "")
        if "." in fraction or len(fraction) > 2:
            self.template_error(dynpro_field)
        groups = whole.split(".")
        if len(groups) > 1:
            # Thousands separators have to group the digits in threes.
            if not 1 <= len(groups[0]) <= 3 or any(len(g) != 3 for g in groups[1:]):
                self.template_error(dynpro_field)
        digits = "".join(groups)
        if len(digits.lstrip("0")) > PRICE_INTEGER_DIGITS:
            self.format_error(dynpro_field, "Entry too long (enter in the format __.___.___.___,__)")
        return "%s.%s" % (digits or "0", (fraction + "00")[:2])

    def template_error(self, dynpro_field):
        self.format_error(dynpro_field, "Input must be in the format __.___.___.___,__")

    def format_error(self, dynpro_field, detail):
        """What the dynpro puts on the status line, then it stops the case."""
        self.client.ui("E", "Formatting error in the field %s; see next message" % dynpro_field)
        self.client.ui("E", detail)
        raise Stop()

    # -- the two screens -------------------------------------------------------

    def step(self, step):
        want = str(step.get("screen", "")).zfill(4)
        if want != self.screen:
            # Batch input found no data for the screen the program put up.
            raise Stop()
        fields = step.get("fields") or {}
        code = (step.get("ok") or "").upper()
        if self.screen == "0100":
            self.step_0100(fields, code)
        else:
            self.step_0200(fields, code)

    def step_0100(self, fields, code):
        for name, raw in fields.items():
            if name.upper() != "ZRET_S_ART-ARTICLE_ID":
                raise Stop()
            self.article_id = self.typed(raw, 20, TEXT, "ZRET_S_ART-ARTICLE_ID")
        if code in LEAVE_CODES:
            # The program leaves. Nothing is written.
            raise Stop()
        if code not in GO_CODES:
            return
        if not self.article_id:
            # The article is a required field of the dynpro, so the screen never
            # reaches the program with it empty.
            self.client.ui("E", "Formatting error in the field ZRET_S_ART-ARTICLE_ID; see next message")
            self.client.ui("E", 'Make an entry in mandatory field "Article"')
            raise Stop()
        self.load()
        self.screen = "0200"
        self.tab = "TAB1"

    def load(self):
        """Open the article, the way the list report does. An article that is not
        there is a new one, and the old program pre-fills three of its fields."""
        where = quote("ArticleId eq '%s'" % self.article_id.replace("'", "''"), safe="")
        found = self.client.get("%s?$filter=%s&$expand=%s" % (ARTICLES, where, VARIANTS))

